def hmacSha256(String data, String key) {
    try {
        Mac mac = Mac.getInstance("HmacSHA256")
        SecretKeySpec secretKeySpec = new SecretKeySpec(key.getBytes(), "HmacSHA256")
        mac.init(secretKeySpec)
        return mac.doFinal(data.getBytes())
    } catch (NoSuchAlgorithmException | InvalidKeyException e) {
        throw new RuntimeException("Error al calcular HMAC SHA256", e)
    }
}

import javax.crypto.Mac
import javax.crypto.spec.SecretKeySpec
import java.security.InvalidKeyException
import java.security.NoSuchAlgorithmException
import groovy.json.JsonSlurper
import java.time.Instant
import java.util.*

// Definir testCaseAlreadyRun para rastrear los casos de prueba que ya se han ejecutado
def testCaseAlreadyRun = [:]

// Función para ejecutar un Test Step y obtener la respuesta
def runTestStep(testSuiteName, testCaseName, testStepName) {
    def testSuite = testRunner.testCase.testSuite.project.getTestSuiteByName(testSuiteName)
    def testCase = testSuite.getTestCaseByName(testCaseName)
    def testStep = testCase.getTestStepByName(testStepName)

    if (testStep == null) {
        log.error "Test Step '${testStepName}' no encontrado en el Test Case '${testCaseName}' del Test Suite '${testSuiteName}'"
        return null
    }

    def testStepResult = testStep.run(testRunner, context)

    if (testStepResult.getStatus().toString() == "FAILED") {
        log.error "El Test Step '${testStepName}' falló en el Test Case '${testCaseName}' del Test Suite '${testSuiteName}'"
        return null
    } else {
        log.info "El Test Step '${testStepName}' se ejecutó correctamente en el Test Case '${testCaseName}' del Test Suite '${testSuiteName}'"
    }

    def responseContent = testStepResult.getResponse().getContentAsString()
    log.info "Respuesta del Test Step '${testStepName}' en el Test Case '${testCaseName}' del Test Suite '${testSuiteName}': ${responseContent}"

    return responseContent
}

// Función para extraer un valor de una respuesta JSON
def extractValueFromJsonResponse(response, key) {
    def jsonSlurper = new groovy.json.JsonSlurper()
    def jsonResponse = jsonSlurper.parseText(response)
    return jsonResponse[key]
}

// Ejecución del flujo basado en el documento proporcionado

// Función para ejecutar un TestCase si no ha sido ejecutado previamente
def TestCaseEnginne(String TestSuiteByName, String TestCaseByName) {
    if (testCaseAlreadyRun[TestCaseByName]) {
        log.warn "Test Case '${TestCaseByName}' ya ha sido ejecutado. Saltando..."
        return
    }

    testCaseAlreadyRun[TestCaseByName] = true

    def testSuite = testRunner.testCase.testSuite.project.getTestSuiteByName(TestSuiteByName)
    def testCase = testSuite.getTestCaseByName(TestCaseByName)
    def totalTestSteps = testCase.getTestSteps().size()

    log.info testSuite
    log.info testCase
    log.info totalTestSteps

    for (n in (0..totalTestSteps - 1)) {
        log.info "------------------------------------------------------------"
        def testStepName = testCase.getTestStepAt(n).name
        log.info testStepName
        log.info n

        if (n >= 0) {
            if (testCase.getTestStepByName(testStepName).disabled != true) {
                log.info "testStepName: " + n + ": " + testStepName
                def testStep = testCase.getTestStepByName(testStepName)
                def runner = testStep.run(testRunner, context)
                log.info("testStep   >>> 1   " + runner.getStatus().toString())
            }
        }
    }
}

